":"workhub_private.actor_context","secdef":true}],["function","workhub_private.op1_actor_transitions(p_member_id text, p_lock boolean)",{"eff":"","body":"a2d48a10558aea54688019e310a3892c","exec":"","lang":"sql","config":"search_path=\"\"","result":"workhub_private.actor_context","secdef":true}],["function","workhub_private.op1_allowed(p_school text, p_member text, p_scope text)",{"eff":"","body":"86f076f3c3c3f468b9653a5f78beadc0","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable(p_school text, p_member text, p_scope text)",{"eff":"","body":"d0c17c9c1e08a457f2d05468ad9fb4f5","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_calendar(p_school text, p_member text)",{"eff":"","body":"ccecfb4eaca642b4ffa80809f0886175","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_collections(p_school text, p_member text)",{"eff":"","body":"00435eecc8e0a264bf6bb533960c44eb","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_cooperation(p_school text, p_member text)",{"eff":"","body":"c08767ea243fb8d77efe5aca1885d891","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_messages(p_school text, p_member text)",{"eff":"","body":"4cc325e978b9a3cd6bf647dec7f00a02","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_tasks(p_school text, p_member text)",{"eff":"","body":"6c5bd02c54b310cb9ada1fed250275a2","exec":"","lang":"sql","config":"search_path=\"\"","result":"boolean","secdef":true}],["function","workhub_private.op1_reachable_teaching(p_school text, p_member text)",{"eff":"","body":"cbdda802d788f6bb0674e5678b5f701f","exec":"","